import React, { useState, useCallback, useEffect } from 'react';

import { ChromeMessagingAction } from 'models/ChromeMessaging';

import { UILoader } from 'components/UI/Loader/UILoader';

import { useFlowContext } from 'context/FlowContext';
import { PageCaptureDevtools } from 'lib/PageCapture/PageCaptureDevtools';

import { SnapperRecorderDeviceInfo } from './DeviceInfo/SnapperRecorderDeviceInfo';
import { SnapperRecorderItem } from './Item/SnapperRecorderItem';

import styles from './SnapperRecorder.module.scss';

export function SnapperRecorder(props: { onBack: () => void }): JSX.Element | null {
  const { onBack } = props;

  const {
    error,
    isLoading: isSnapshotting,
    selectedFlow: flow,
    methdos: { doSnapshot, updateFlowPage, deleteFlowPage },
  } = useFlowContext();

  const [isLoading, setIsLoading] = useState(false);
  const [shortcutLabel, setShortcutLabel] = useState('');

  const handleCapturePage = useCallback(async () => {
    await doSnapshot();
  }, [doSnapshot]);

  const handleDownloadFlow = useCallback(() => {
    if (flow) {
      setIsLoading(true);
      PageCaptureDevtools.zipFlow(flow, `${flow.name}.zip`).then(() => {
        setIsLoading(false);
      });
    }
  }, [flow]);

  const computeSize = useCallback(() => {
    if (flow) {
      let sizes: Record<string, number> = {};
      flow.pages.forEach((page) => {
        sizes = {
          ...sizes,
          ...page.mapSizes,
        };
      });
      let totalSize = 0;
      Object.values(sizes).forEach((size) => {
        totalSize += size;
      });
      return (totalSize / (1024 * 1024)).toFixed(0);
    }
    return 0;
  }, [flow]);

  useEffect(() => {
    chrome.runtime.getPlatformInfo((info) => {
      setShortcutLabel(info.os === 'win' ? '(ctrl+shift+s)' : '(cmd+shift+s)');
    });
  }, []);

  useEffect(() => {
    function doSnapshotFromBackground(message: { action: ChromeMessagingAction.DO_SNAPSHOT }): void {
      if (message.action === ChromeMessagingAction.DO_SNAPSHOT) {
        handleCapturePage();
      }
    }

    chrome.runtime.onMessage.addListener(doSnapshotFromBackground);
    return () => {
      chrome.runtime.onMessage.removeListener(doSnapshotFromBackground);
    };
  }, [handleCapturePage]);

  if (!flow) {
    return null;
  }

  return (
    <div className={styles['snapper-recorder']}>
      {isLoading || (isSnapshotting && <UILoader />)}
      <div className={styles.header}>
        <button className="btn-link" onClick={onBack}>
          ‹ Back
        </button>
        <h2>{flow.name}</h2>
      </div>
      <div>
        <p>
          To be sure to capture all the page resources, please disable the cache by checking the &apos;Disable
          Cache&apos; on &apos;Network&apos; tab.
        </p>
      </div>

      <div className={styles['flow-info']}>
        <div>
          <SnapperRecorderDeviceInfo selectedFlow={flow} />
          <div>Steps: {flow.pages.length}</div>
          <div>Size: ~{computeSize()}MB</div>
        </div>
        <button onClick={handleDownloadFlow} className="btn btn-secondary">
          Download flow
        </button>
      </div>
      <ol>
        {flow.pages.map((page) => (
          <SnapperRecorderItem
            page={page}
            key={page.id}
            onUpdateFlowPage={updateFlowPage}
            onDeleteFlowPage={deleteFlowPage}
          />
        ))}
      </ol>
      {error && <div className="error-msg">{error}</div>}

      <div className={styles['flow-actions']}>
        <button onClick={handleCapturePage} className="btn btn-primary">
          Capture page
        </button>
        <span style={{ marginLeft: '10px' }}>{shortcutLabel}</span>
      </div>
    </div>
  );
}
