import { executePageFunction, getTabId, sendBackgroundMessage } from 'lib/ChromeUtils';
import { getDevice } from 'lib/Devices';

import { ChromeMessagingAction } from 'models/ChromeMessaging';
import type { Flow } from 'models/Flow';
import type { NetworkResource } from 'models/StorageResouces';
import type { PresetDevice, CustomDevice } from 'models/Devices';
import { DeviceId } from 'models/Devices';

import { getPageViewport } from 'lib/Utils';

import { PageCaptureCore } from './PageCaptureCore';

/**
 * Class that handles the page capture process.
 * The main sources used to build the final snapshot are:
 * - chrome native MHTM snapshot for external CSS and to map the external iframes
 * - network recording for images and fonts
 * - content script snapshot.js for the HTML
 */
export class PageCaptureDevtools extends PageCaptureCore {
  static calculateSize(content: string, encoding: string): number {
    if (encoding === 'base64') {
      // eslint-disable-next-line no-nested-ternary
      return (content.length * 3) / 4 - (content.endsWith('==') ? 2 : content.endsWith('=') ? 1 : 0);
    }
    return content.length;
  }

  async doSnapshot(selectedFlow: Flow): Promise<{ success: false; error: string } | { success: true }> {
    if (selectedFlow) {
      const scaleFactor = await executePageFunction<number>(() => {
        return window.devicePixelRatio;
      });

      if (scaleFactor !== selectedFlow.scaleFactor) {
        return {
          success: false,
          error:
            'Error: monitor pixel ratio changed. Please create a new flow or use the monitor where the flow has been created.',
        };
      }

      let device: CustomDevice | PresetDevice | null = null;
      if (selectedFlow.device === DeviceId.CUSTOM) {
        if (selectedFlow.pageViewport) {
          const currentViewport = await getPageViewport();
          if (
            currentViewport?.innerWidth !== selectedFlow.pageViewport.innerWidth ||
            currentViewport?.innerHeight !== selectedFlow.pageViewport.innerHeight
          ) {
            return {
              success: false,
              error: 'viewport is changed, please restore the initial viewport or create a new flow',
            };
          }
          device = {
            id: DeviceId.CUSTOM,
            name: DeviceId.CUSTOM,
            viewport: {
              width: selectedFlow.pageViewport.innerWidth,
              height: selectedFlow.pageViewport.innerHeight,
              touch: selectedFlow.pageViewport.touch,
            },
          };
        }
      } else {
        device = getDevice(selectedFlow.device);
      }
      if (device) {
        await sendBackgroundMessage({
          action: ChromeMessagingAction.RESIZE_WINDOW,
          device,
        });

        const tabId = await getTabId();
        const preview = await new Promise<string>((resolve) => {
          chrome.debugger.sendCommand(
            { tabId },
            'Page.captureScreenshot',
            {
              quality: 5,
              fomat: 'jpeg',
            },
            (response) => {
              if (chrome.runtime.lastError) {
                console.error(chrome.runtime.lastError);
              }
              if (response && 'data' in response && typeof response.data === 'string') {
                resolve(`data:image/jpeg;base64, ${response.data}`);
              } else {
                resolve('');
              }
            },
          );
        });
        const capturedPage = await this.capturePage(undefined, preview);
        if (capturedPage) {
          selectedFlow.pages.push(capturedPage);
          await PageCaptureDevtools.updateFlowCollection(selectedFlow);
          return { success: true };
        }
      } else {
        return { success: false, error: 'device not valid' };
      }
    }
    return { success: false, error: 'no selected flow' };
  }

  networkListener(request: chrome.devtools.network.Request): void {
    if (
      request._resourceType &&
      ['image', 'font', 'stylesheet'].includes(request._resourceType) &&
      !request.request.url.startsWith('data:')
    ) {
      const contentTypeHeader = request.response.headers.find((header) => header.name.toLowerCase() === 'content-type');
      request.getContent((content, encoding) => {
        if (content === null) {
          fetch(request.request.url).then((response) => {
            if (response.ok) {
              response.arrayBuffer().then((arrayBuffer) => {
                const base64String = btoa(String.fromCharCode(...new Uint8Array(arrayBuffer)));
                const key = new Date().getTime().toString(16) + Math.random().toString(36).substr(2);
                const sr: NetworkResource = {
                  url: request.request.url ?? '',
                  content: base64String,
                  encoding: 'base64',
                  size: PageCaptureDevtools.calculateSize(base64String, 'base64'),
                  contentType: contentTypeHeader ? contentTypeHeader.value : request.response.content.mimeType,
                };
                this.resourcesMap[key] = sr;
                this.resourcesList.push(key);
              });
            } else {
              console.log('TO NOTIFY ABOUT THE ERROR');
            }
          });
        } else {
          const key = new Date().getTime().toString(16) + Math.random().toString(36).substr(2);
          const sr: NetworkResource = {
            url: request.request.url ?? '',
            content,
            encoding,
            // calculate size based on encoding
            size: PageCaptureDevtools.calculateSize(content, encoding),
            contentType: contentTypeHeader ? contentTypeHeader.value : request.response.content.mimeType,
          };
          this.resourcesMap[key] = sr;
          this.resourcesList.push(key);
        }
      });
    }
  }
}
