import type { ReactEventHandler } from 'react';
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';

import classNames from 'classnames';

import styles from './SnapperRecorderItemPreview.module.scss';

export function SnapperRecorderItemPreview(props: { imageSrc: string }): JSX.Element {
  const { imageSrc } = props;

  const [isZoomming, setIsZoomming] = useState(false);
  const [thumbImageSize, setThumbImageSize] = useState({ w: 0, h: 0 });
  const [zoomImageSize, setZoomImageSize] = useState({ w: 0, h: 0 });
  const [heightRatio, setHeightRatio] = useState(1);
  const [widthRatio, setWidthRatio] = useState(1);
  const [mousePosition, setMousePosition] = useState({ x: 0, y: 0 });
  const [orientation, setOrientation] = useState<'h' | 'v'>('h');

  const [zoomPosition, setZoomPosition] = useState<'bottom' | 'top'>('bottom');

  const zoom = useRef<HTMLDivElement | null>(null);

  const getImageThumbSize = useCallback<ReactEventHandler<HTMLImageElement>>((e) => {
    const { currentTarget } = e;
    setThumbImageSize({ h: currentTarget.height, w: currentTarget.width });
  }, []);

  const getImageSize = useCallback<ReactEventHandler<HTMLImageElement>>((e) => {
    const { currentTarget } = e;
    setZoomImageSize({ h: currentTarget.height, w: currentTarget.width });
  }, []);

  const getPreviewMousePosition = useCallback<React.MouseEventHandler<HTMLImageElement>>((e) => {
    const { clientX, clientY, currentTarget } = e;

    const rect = currentTarget.getBoundingClientRect();
    const x = clientX - rect.left;
    const y = clientY - rect.top;

    setMousePosition({ x, y });
  }, []);

  const toggleZoomPosition = useCallback(() => {
    setZoomPosition((prevValue) => (prevValue === 'bottom' ? 'top' : 'bottom'));
  }, []);

  const onExtensionResize = useCallback(() => {
    if (window.innerWidth > window.innerHeight) {
      setOrientation('h');
    } else {
      setOrientation('v');
    }
  }, []);

  const enableZoomming = useCallback(() => {
    setIsZoomming(true);
  }, []);

  const disableZoomming = useCallback(() => {
    setIsZoomming(false);
  }, []);

  useEffect(() => {
    if (thumbImageSize.w && zoomImageSize.w) {
      setHeightRatio(zoomImageSize.h / thumbImageSize.h);
      setWidthRatio(zoomImageSize.w / thumbImageSize.w);
    }
  }, [zoomImageSize.w, zoomImageSize.h, thumbImageSize.w, thumbImageSize.h]);

  useEffect(() => {
    onExtensionResize();
    window.addEventListener('resize', onExtensionResize);
    return () => {
      window.removeEventListener('resize', onExtensionResize);
    };
  }, [onExtensionResize]);

  const translateZoommedPreview = useMemo(() => {
    let x = heightRatio * mousePosition.x;
    let y = widthRatio * mousePosition.y;

    if (zoom.current) {
      const zoomCont = zoom.current;
      const zoomContRect = zoomCont.getBoundingClientRect();
      if (y > zoomImageSize.h - zoomContRect.height) {
        y = zoomImageSize.h - zoomContRect.height;
      } else if (y < 0) {
        y = 0;
      }
      if (zoomImageSize.w < zoomContRect.width) {
        x = 0;
      } else if (x > zoomImageSize.w - zoomContRect.width) {
        x = zoomImageSize.w - zoomContRect.width;
        if (x + zoomContRect.width >= zoomImageSize.w) {
          x = zoomImageSize.w - zoomContRect.width;
        }
      } else if (x < 0) {
        x = 0;
      }
    }
    return { transform: `translate(${x * -1}px,${y * -1}px)` };
  }, [heightRatio, zoomImageSize.w, zoomImageSize.h, mousePosition.x, mousePosition.y, widthRatio]);

  return (
    <>
      <div className={classNames(styles['item-preview'], { [styles.zoomming]: isZoomming })}>
        <img
          src={imageSrc}
          onLoad={getImageThumbSize}
          onMouseMove={getPreviewMousePosition}
          onMouseOver={enableZoomming}
          onMouseLeave={disableZoomming}
        />

        <div
          className={classNames(styles['item-preview-zoom'], styles[orientation], styles[zoomPosition])}
          ref={zoom}
          onMouseOver={toggleZoomPosition}>
          <img src={imageSrc} onLoad={getImageSize} style={translateZoommedPreview} />
        </div>
      </div>
    </>
  );
}
