import React, { useCallback, useState } from 'react';

import { useFlowContext } from 'context/FlowContext';
import { Devices } from 'lib/Devices';

import type { PresetDevice } from 'models/Devices';

import { SnapperAddNewFlowDevice } from './Device/SnapperAddNewFlowDevice';

import styles from './SnapperAddNewFlow.module.scss';

interface SnapperAddNewFlowProps {
  onCancel: () => void;
}

export function SnapperAddNewFlow(props: SnapperAddNewFlowProps): JSX.Element {
  const { onCancel } = props;

  const {
    isLoading,
    methdos: { addFlowCollection },
  } = useFlowContext();

  const [newFlowName, setNewFlowName] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [selectedDevice, setSelectedDevice] = useState<PresetDevice['id'] | null>(Devices[0].id);

  const handleNewFlowNameChange = useCallback<React.ChangeEventHandler<HTMLInputElement>>((e) => {
    const {
      currentTarget: { value },
    } = e;
    setError(null);
    setNewFlowName(value);
  }, []);

  const handleAddNewFlow = useCallback(async () => {
    if (selectedDevice !== null) {
      if (newFlowName.trim() === '') {
        setError('Flow name cannot be empty.');
        return;
      }
      const response = await addFlowCollection(newFlowName, selectedDevice);
      if (response === null) {
        setError('Flow name already exists.');
        return;
      }
      onCancel();
    }
  }, [addFlowCollection, newFlowName, onCancel, selectedDevice]);

  return (
    <div className={styles['add-new']}>
      <div className="form">
        <div className={styles['add-new-field']}>
          <input
            type="text"
            id="new-flow-name"
            placeholder="New flow name"
            value={newFlowName}
            onChange={handleNewFlowNameChange}
          />
          {error && <div className={styles['form-error']}>{error}</div>}
        </div>
        <SnapperAddNewFlowDevice onDeviceSelect={setSelectedDevice} />
        <div className={styles.actions}>
          <button
            className="btn btn-primary"
            disabled={selectedDevice === null || newFlowName.trim() === '' || isLoading}
            onClick={handleAddNewFlow}>
            {isLoading ? 'Adding...' : 'Add'}
          </button>
          <button className="btn btn-secondary" onClick={onCancel}>
            Cancel
          </button>
        </div>
      </div>
    </div>
  );
}
