import React, { useCallback, useState } from 'react';

import type { Flow } from 'models/Flow';

import { ErrorPanel } from 'components/UI/ErrorPanel/ErrorPanel';

import styles from './SnapperRecorderItem.module.scss';
import { SnapperRecorderItemPreview } from './Preview/SnapperRecorderItemPreview';

interface SnapperRecorderItemProps {
  page: Flow['pages'][0];
  onDeleteFlowPage: (updatedFlow: Flow['pages'][0]) => Promise<void>;
  onUpdateFlowPage: (updatedFlow: Flow['pages'][0], deletePage?: boolean) => void;
}

export function SnapperRecorderItem(props: SnapperRecorderItemProps): JSX.Element {
  const { page, onDeleteFlowPage, onUpdateFlowPage } = props;
  const [isEditing, setIsEditing] = useState(false);
  const [editName, setEditName] = useState(page.name);
  const [error, setError] = useState<string | null>(null);

  const handleNameChange = useCallback<React.ChangeEventHandler<HTMLInputElement>>((e) => {
    const { currentTarget } = e;
    setEditName(currentTarget.value);
  }, []);

  const toggleEdit = useCallback(() => {
    setIsEditing((prevValue) => !prevValue);
  }, []);

  const handleDelete = useCallback(() => {
    onDeleteFlowPage({ ...page });
  }, [onDeleteFlowPage, page]);

  const handleDoneEdit = useCallback(() => {
    if (editName.trim().length === 0) {
      setError('Name cannot be empty.');
      return;
    }
    if (editName.length > 255) {
      setError('Name cannot be longer than 255 characters.');
      return;
    }
    setError(null);

    onUpdateFlowPage({ ...page, name: editName });
    toggleEdit();
  }, [editName, onUpdateFlowPage, page, toggleEdit]);

  const handleFocus = useCallback<React.FocusEventHandler<HTMLInputElement>>((e): void => {
    const target = e.target;
    target.select();
  }, []);

  return (
    <li className={styles.item} key={page.id}>
      <div className={styles['item-top']}>
        <div className={styles['item-info']}>
          <SnapperRecorderItemPreview imageSrc={page.preview} />
          {isEditing ? (
            <div className={styles['item-name']}>
              <div className={styles['item-name-value']}>
                <input
                  onChange={handleNameChange}
                  type="text"
                  autoFocus
                  spellCheck="false"
                  onFocus={handleFocus}
                  value={editName}
                  onBlur={handleDoneEdit}
                />
                {error && (
                  <ErrorPanel
                    message={error}
                    onClose={(): void => {
                      setError(null);
                    }}
                  />
                )}
              </div>
              <div className={styles['item-controls']}>
                <button className="btn-link" onClick={handleDoneEdit}>
                  Done
                </button>
              </div>
            </div>
          ) : (
            <div className={styles['item-name']}>
              <div className={styles['item-name-value']}>{page.name ?? 'unnamed '}</div>
              <div className={styles['item-controls']}>
                <button className="btn-link" onClick={toggleEdit}>
                  Rename
                </button>
                <button className="btn-link warning" onClick={handleDelete}>
                  Delete
                </button>
              </div>
            </div>
          )}
        </div>
      </div>
      <div className={styles['item-bottom']}>
        <div className={styles['item-uri']}>{page.uri}</div>
      </div>
    </li>
  );
}
