import React, { useMemo } from 'react';

import { Devices } from 'lib/Devices';

import type { Flow } from 'models/Flow';

import styles from './SnapperRecorderDeviceInfo.module.scss';

export function SnapperRecorderDeviceInfo(props: { selectedFlow: Flow }): JSX.Element | null {
  const { selectedFlow } = props;

  const device = useMemo(() => {
    return Devices.find((_device) => _device.id === selectedFlow.device);
  }, [selectedFlow.device]);

  if (device) {
    return (
      <div className={styles['device-info']}>
        Viewport: {device.viewport.width} x {device.viewport.height}
      </div>
    );
  }

  return null;
}
