import React, { useCallback, useState } from 'react';

import { UIViewContent } from 'components/UI/ViewContent/UIViewContent';
import { useFlowContext } from 'context/FlowContext';

import { SnapperRecorder } from './Recorder/SnapperRecorder';
import { SnapperAddNewFlow } from './AddNewFlow/SnapperAddNewFlow';
import { SnapperFlow } from './SnapperFlow';

export function Snapper(): JSX.Element {
  const [isAddingFlow, setIsAddingFlow] = useState(false);

  const {
    flowCollection,
    selectedFlow,
    methdos: { selectFlow },
  } = useFlowContext();

  const handleToggleAddFlow = useCallback(() => {
    setIsAddingFlow((prevValue) => !prevValue);
  }, []);

  const handleCancelAddFlow = useCallback(() => {
    setIsAddingFlow(false);
  }, []);

  const handleBackToSelection = useCallback(() => {
    selectFlow(null);
  }, [selectFlow]);

  return (
    <div>
      {selectedFlow ? (
        <SnapperRecorder onBack={handleBackToSelection} />
      ) : (
        <UIViewContent>
          <div id="flow-collection">
            {flowCollection && flowCollection?.length > 0 ? (
              <>
                <h2>Flow collection</h2>
                <p>
                  Select a flow or{' '}
                  <button className="btn-link" onClick={handleToggleAddFlow}>
                    create
                  </button>{' '}
                  a new one.
                </p>
              </>
            ) : (
              <h2>Create a new flow</h2>
            )}

            {/* Show new flow form */}
            <div>
              {(isAddingFlow || flowCollection === undefined || flowCollection?.length === 0) && (
                <SnapperAddNewFlow onCancel={handleCancelAddFlow} />
              )}
            </div>

            {/* Show flow list */}
            {!isAddingFlow && flowCollection?.map((flow) => <SnapperFlow key={flow.name} flow={flow} />)}
          </div>
        </UIViewContent>
      )}
    </div>
  );
}
