import React, { useCallback, useEffect, useState } from 'react';

import classNames from 'classnames';

import styles from './ErrorPanel.module.scss';

export function ErrorPanel(props: { message: string; onClose: () => void }): JSX.Element | null {
  const { message, onClose } = props;

  const [visible, setVisible] = useState(true);

  const handleClosePanel = useCallback(() => {
    onClose();
  }, [onClose]);

  useEffect(() => {
    setVisible(true);
  }, [message]);

  if (!visible) {
    return null;
  }

  return (
    <div className={classNames(styles['error-panel'])}>
      <div className={styles['error-panel-message']}>{message}</div>
      <button onClick={handleClosePanel} />
    </div>
  );
}
