import type { ReactNode } from 'react';
import React, { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react';

import type { PlatformStorage } from 'models/ChromeStorage';
import { getFromStorage, sendBackgroundMessage } from 'lib/ChromeUtils';
import type { ChromeMsgResizeWindow } from 'models/ChromeMessaging';
import { ChromeMessagingAction } from 'models/ChromeMessaging';
import type { Flow } from 'models/Flow';
import { getDevice } from 'lib/Devices';
import { PageCaptureDevtools } from 'lib/PageCapture/PageCaptureDevtools';
import { DeviceId, type PresetDevice } from 'models/Devices';

export interface FlowData {
  error: string | null;
  flowCollection: PlatformStorage['flowCollection'];
  isLoading: boolean;
  selectedFlow: Flow | null;
  selectedFlowCollection: number | null;
  methdos: {
    addFlowCollection: (flowName: string, device: PresetDevice['id']) => Promise<Flow | null>;
    deleteFlowCollection: (flowToDelete: Flow) => Promise<void>;
    deleteFlowPage: (page: Flow['pages'][0]) => Promise<void>;
    doSnapshot: () => Promise<{ success: false; error: string } | { success: true }>;
    downloadFlow: () => Promise<void>;
    removeResources: (resources: string[]) => void;
    selectFlow: (flow: Flow | null) => Promise<{ success: false; error: string } | { success: true }>;
    updateFlowCollection: (updatedFlow: Flow) => Promise<void>;
    updateFlowPage: (page: Flow['pages'][0], deletePage?: boolean) => void;
  };
}

const FlowContext = createContext<FlowData>({} as FlowData);

export function useFlowContext(): FlowData {
  return useContext(FlowContext);
}

export function FlowProvider(props: { children: ReactNode }): JSX.Element {
  const { children } = props;

  const [flowCollection, setFlowCollection] = useState<PlatformStorage['flowCollection']>([]);
  const [selectedFlowCollection, setSelectedFlowCollection] = useState<number | null>(null);
  const [selectedFlow, setSelectedFlow] = useState<Flow | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const pageCaptureClass = useRef<PageCaptureDevtools | null>(null);

  /**************************************************************
   *                  STORAGE OPERATIONS
   **************************************************************/
  const loadDataFromStorage = useCallback(async () => {
    const result = await getFromStorage<PlatformStorage>(['flowCollection']);
    if (result?.flowCollection) {
      setFlowCollection([...result.flowCollection]);
    }
  }, []);

  const reloadFromStorage = useCallback(
    (message: { action: ChromeMessagingAction }) => {
      if (message.action === ChromeMessagingAction.RELOAD_FLOW_COLLECTION) {
        loadDataFromStorage();
      }
    },
    [loadDataFromStorage],
  );

  /**************************************************************
   *                 FLOW COLLECTION OPERATIONS
   **************************************************************/
  const removeResources = useCallback(
    async (resources: string[]) => {
      if (pageCaptureClass.current) {
        const deleteResources = pageCaptureClass.current.deleteResources.bind(pageCaptureClass.current);

        await deleteResources(resources);
        await loadDataFromStorage();
      }
      return null;
    },
    [loadDataFromStorage],
  );

  const updateFlowCollection = useCallback(
    async (updatedFlow: Flow) => {
      if (pageCaptureClass.current) {
        await PageCaptureDevtools.updateFlowCollection(updatedFlow);
        await loadDataFromStorage();
      }
    },
    [loadDataFromStorage],
  );

  const addFlowCollection = useCallback(
    async (flowName: string, device: PresetDevice['id']): Promise<Flow | null> => {
      setIsLoading(true);

      if (pageCaptureClass.current) {
        const result = await PageCaptureDevtools.addFlowCollection(flowName, device);
        await loadDataFromStorage();
        setIsLoading(false);
        return result;
      }
      setIsLoading(false);
      return null;
    },
    [loadDataFromStorage],
  );

  const deleteFlowCollection = useCallback(
    async (flowToDelete: Flow) => {
      setIsLoading(true);
      if (pageCaptureClass.current) {
        const _deleteFlowCollection = pageCaptureClass.current.deleteFlowCollection.bind(pageCaptureClass.current);
        await _deleteFlowCollection(flowToDelete);
        await loadDataFromStorage();
      }
      setIsLoading(false);
    },
    [loadDataFromStorage],
  );

  const downloadFlow = useCallback(async () => {
    if (selectedFlow) {
      setIsLoading(true);
      await PageCaptureDevtools.zipFlow(selectedFlow, `${selectedFlow.name}.zip`);
      setIsLoading(false);
    }
  }, [selectedFlow]);

  /**************************************************************
   *                 SINGLE FLOW OPERATIONS
   **************************************************************/
  const updateFlowPage = useCallback(
    async (page: Flow['pages'][0], deletePage?: boolean) => {
      if (selectedFlow) {
        if (pageCaptureClass.current) {
          await PageCaptureDevtools.updateFlowPage(page, selectedFlow, deletePage);
          await loadDataFromStorage();
        }
      }
    },
    [loadDataFromStorage, selectedFlow],
  );

  const deleteFlowPage = useCallback(
    async (page: Flow['pages'][0]) => {
      if (selectedFlow) {
        if (pageCaptureClass.current) {
          const _deleteFlowPage = pageCaptureClass.current.deleteFlowPage.bind(pageCaptureClass.current);
          await _deleteFlowPage(page, selectedFlow);
          await loadDataFromStorage();
        }
      }
    },
    [selectedFlow, loadDataFromStorage],
  );

  const selectFlow = useCallback<FlowData['methdos']['selectFlow']>(async (flow: Flow | null) => {
    if (flow === null) {
      setSelectedFlowCollection(null);
      setSelectedFlow(null);
      return { success: true };
    }
    if (flow.device === DeviceId.CUSTOM) {
      if (flow.pageViewport) {
        await sendBackgroundMessage<ChromeMsgResizeWindow>({
          action: ChromeMessagingAction.RESIZE_WINDOW,
          device: {
            id: DeviceId.CUSTOM,
            name: DeviceId.CUSTOM,
            viewport: {
              width: flow.pageViewport.innerWidth,
              height: flow.pageViewport.innerHeight,
              touch: flow.pageViewport.touch,
            },
          },
          reload: true,
        });

        setSelectedFlowCollection(flow.date);
        return { success: true };
      }
    } else {
      const device = getDevice(flow.device);
      if (device) {
        await sendBackgroundMessage<ChromeMsgResizeWindow>({
          action: ChromeMessagingAction.RESIZE_WINDOW,
          device,
          reload: true,
        });

        setSelectedFlowCollection(flow.date);
        return { success: true };
      }
    }
    return { success: false, error: `Unable to select flow ${flow.name}` };
  }, []);

  /**************************************************************
   *                       SNAPSHOTTER
   **************************************************************/
  const doSnapshot = useCallback<FlowData['methdos']['doSnapshot']>(async () => {
    setIsLoading(true);
    setError(null);
    if (selectedFlow) {
      if (pageCaptureClass.current) {
        const _doSnapshot = pageCaptureClass.current.doSnapshot.bind(pageCaptureClass.current);
        const result = await _doSnapshot(selectedFlow);
        await loadDataFromStorage();
        if (!result.success) {
          setError(result.error);
          setIsLoading(false);
          return { success: false, error: result.error };
        }
        setIsLoading(false);
        return { success: true };
      }
    }
    setIsLoading(false);
    return { success: false, error: 'no selected flow' };
  }, [loadDataFromStorage, selectedFlow]);

  /**************************************************************
   *                        USE EFFECT
   **************************************************************/
  useEffect(() => {
    loadDataFromStorage();
  }, [loadDataFromStorage]);

  useEffect(() => {
    chrome.runtime.onMessage.addListener(reloadFromStorage);
    return (): void => {
      chrome.runtime.onMessage.removeListener(reloadFromStorage);
    };
  }, [reloadFromStorage]);

  useEffect(() => {
    if (pageCaptureClass.current === null) {
      pageCaptureClass.current = new PageCaptureDevtools();
      const networkListener = pageCaptureClass.current.networkListener.bind(pageCaptureClass.current);
      chrome.devtools.network.onRequestFinished.addListener(networkListener);
      return () => {
        chrome.devtools.network.onRequestFinished.removeListener(networkListener);
      };
    }
    return () => {};
  }, []);

  useEffect(() => {
    const _flow = flowCollection?.find((flow) => flow.date === selectedFlowCollection);
    if (_flow) {
      setSelectedFlow({ ..._flow });
    } else {
      setSelectedFlow(null);
    }
  }, [flowCollection, selectedFlowCollection]);

  const flowData = useMemo<FlowData>(
    () => ({
      error,
      flowCollection,
      isLoading,
      selectedFlow,
      selectedFlowCollection,
      methdos: {
        addFlowCollection,
        deleteFlowCollection,
        deleteFlowPage,
        doSnapshot,
        downloadFlow,
        removeResources,
        selectFlow,
        updateFlowCollection,
        updateFlowPage,
      },
    }),
    [
      addFlowCollection,
      deleteFlowCollection,
      deleteFlowPage,
      doSnapshot,
      downloadFlow,
      error,
      flowCollection,
      isLoading,
      removeResources,
      selectFlow,
      selectedFlow,
      selectedFlowCollection,
      updateFlowCollection,
      updateFlowPage,
    ],
  );

  return <FlowContext.Provider value={flowData}>{children}</FlowContext.Provider>;
}
