import React, { useCallback, useState } from 'react';

import { useFlowContext } from 'context/FlowContext';
import type { Flow } from 'models/Flow';

import styles from './SnapperFlow.module.scss';

interface SnapperFlowProps {
  flow: Flow;
}

export function SnapperFlow(props: SnapperFlowProps): JSX.Element {
  const { flow } = props;

  const [isDeleting, setIsDeleting] = useState(false);

  const {
    isLoading,
    methdos: { deleteFlowCollection, selectFlow },
  } = useFlowContext();

  const handleDeleteFlow = useCallback<React.MouseEventHandler<HTMLButtonElement>>(() => {
    setIsDeleting(true);
    deleteFlowCollection(flow).finally(() => {
      setIsDeleting(false);
    });
  }, [deleteFlowCollection, flow]);

  const handleSelectFlow = useCallback<React.MouseEventHandler<HTMLButtonElement>>(() => {
    selectFlow(flow);
  }, [flow, selectFlow]);

  return (
    <div key={flow.name} className={styles['flow-record']}>
      <div className={styles['flow-record-details']}>
        <div className={styles.name}>{flow.name}</div>
        <div className={styles.steps}>{flow.pages.length} steps</div>
      </div>
      <div className={styles['flow-actions']}>
        <button data-id={flow.date} disabled={isLoading} className="btn btn-link" onClick={handleSelectFlow}>
          Select
        </button>
        <button
          data-id={flow.date}
          className={`btn btn-link warning ${styles['btn-delete']}`}
          disabled={isLoading}
          onClick={handleDeleteFlow}>
          {isDeleting ? 'Deleting...' : 'Delete'}
        </button>
      </div>
    </div>
  );
}
