import React, { useCallback, useState } from 'react';

import { Devices, getDevice } from 'lib/Devices';
import { sendBackgroundMessage } from 'lib/ChromeUtils';

import type { ChromeMsgResizeWindow } from 'models/ChromeMessaging';
import { ChromeMessagingAction } from 'models/ChromeMessaging';
import type { PresetDevice, PresetDeviceId } from 'models/Devices';

import styles from './SnapperAddNewFlowDevice.module.scss';

interface SnapperAddNewFlowDeviceProps {
  onDeviceSelect: (deviceId: PresetDevice['id']) => void;
}

export function SnapperAddNewFlowDevice(props: SnapperAddNewFlowDeviceProps): JSX.Element {
  const { onDeviceSelect } = props;
  const [selectedDevice, setSelectedDevice] = useState<PresetDeviceId>(Devices[0].id);

  const handleViewportChange = useCallback<React.ChangeEventHandler<HTMLInputElement>>(
    (e) => {
      const {
        currentTarget: { value },
      } = e;
      setSelectedDevice(value as PresetDeviceId);
      onDeviceSelect(value as PresetDeviceId);
    },
    [onDeviceSelect],
  );

  const handleSetViewport = useCallback(async () => {
    if (selectedDevice) {
      const device = getDevice(selectedDevice);
      if (device) {
        await sendBackgroundMessage<ChromeMsgResizeWindow>({
          action: ChromeMessagingAction.RESIZE_WINDOW,
          device,
          reload: true,
        });
      }
    }
  }, [selectedDevice]);

  return (
    <div className={styles.device}>
      <fieldset>
        <legend>Viewport</legend>
        <div className={styles['device-select']}>
          <div>
            {Devices.map((device) => (
              <div className="radio-wrapper" key={device.id}>
                <label htmlFor={device.id}>
                  <input
                    type="radio"
                    name="viewport"
                    id={device.id}
                    value={device.id}
                    onChange={handleViewportChange}
                    checked={selectedDevice === device.id}
                  />
                  {device.viewport.width} x {device.viewport.height} {device.viewport.touch ? '(touch)' : ''}
                </label>
              </div>
            ))}
          </div>
          <div>
            <button className="btn btn-secondary" onClick={handleSetViewport}>
              Test viewport
            </button>
          </div>
        </div>
      </fieldset>
    </div>
  );
}
